package com.arena.core.training;
import com.arena.core.entity.*;
import com.arena.core.repository.*;
import com.arena.core.service.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class AcademySetupTest {
 CustomerRepository customers=mock(CustomerRepository.class);AcademySportRepository sports=mock(AcademySportRepository.class);AcademyStaffRepository staff=mock(AcademyStaffRepository.class);TrainingBatchRepository batches=mock(TrainingBatchRepository.class);BatchScheduleRepository schedules=mock(BatchScheduleRepository.class);AcademyPlayAreaRepository areas=mock(AcademyPlayAreaRepository.class);
 AcademySetupService service=new AcademySetupService(mock(AcademyAuthorization.class),customers,sports,staff,batches,schedules,areas,mock(AuditService.class));CustomerEntity c;
 @BeforeEach void setup(){c=CustomerEntity.builder().id(10L).version(0L).customerName("Academy").ownerName("Owner").ownerEmail("owner@example.test").ownerPhone("9876543210").ownerManaged(true).build();when(customers.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));}
 AcademySport sport(boolean training,boolean facility){var s=new AcademySport();s.setId(20L);s.setActive(true);s.setTraining(training);s.setSessions(facility);when(sports.findByAcademyIdOrderByName(10L)).thenReturn(List.of(s));return s;}
 @Test void noSportsNeverReadyAndOnlyApplicableStepsCount(){var p=service.evaluate(c);assertEquals(50L,p.get("percentage"));assertEquals("INCOMPLETE",p.get("status"));assertFalse(c.getSetupReviewConfirmed());}
 @Test void facilityOnlyOwnerManagedAcademyNeedsNoTrainingBatch(){sport(false,true);var p=service.evaluate(c);assertEquals(60L,p.get("percentage"));var a=new AcademyPlayArea();a.setSportId(20L);a.setActive(true);when(areas.findByAcademyIdOrderByName(10L)).thenReturn(List.of(a));p=service.evaluate(c);assertEquals(80L,p.get("percentage"));assertEquals("REVIEW_NEEDED",p.get("status"));c.setSetupReviewConfirmed(true);p=service.evaluate(c);assertEquals(100L,p.get("percentage"));assertEquals("READY",p.get("status"));a.setActive(false);p=service.evaluate(c);assertEquals("INCOMPLETE",p.get("status"));assertFalse(c.getSetupReviewConfirmed());a.setActive(true);assertEquals("REVIEW_NEEDED",service.evaluate(c).get("status"));}
 @Test void trainingChecksPersistedScheduleAndOwnerManagedCanCoach(){sport(true,false);var b=new TrainingBatch();b.setId(30L);b.setSportId(20L);b.setStatus("ACTIVE");when(batches.findByAcademyIdOrderByName(10L)).thenReturn(List.of(b));assertEquals("INCOMPLETE",service.evaluate(c).get("status"));when(schedules.findByBatchIdAndActiveTrueOrderByDayOfWeekAscStartTimeAsc(30L)).thenReturn(List.of(new BatchSchedule()));assertEquals("REVIEW_NEEDED",service.evaluate(c).get("status"));c.setOwnerManaged(false);assertEquals("INCOMPLETE",service.evaluate(c).get("status"));}
 @Test void bothIncludesAllSixStepsAndRepeatedEvaluationIsDeterministic(){sport(true,true);var p=service.evaluate(c);assertEquals(50L,p.get("percentage"));assertEquals(p.get("percentage"),service.evaluate(c).get("percentage"));assertEquals(p.get("status"),service.evaluate(c).get("status"));}
 @Test void activeCustomWithoutCapabilitiesCompletesSportsAndInactiveReopensOnlyCurrentProgress(){var s=sport(false,false);s.setName("Jog");s.setCatalogueCode(null);c.setSetupReviewConfirmed(true);var p=service.evaluate(c);assertEquals("READY",p.get("status"));assertEquals(100L,p.get("percentage"));s.setActive(false);p=service.evaluate(c);assertEquals("INCOMPLETE",p.get("status"));assertEquals(50L,p.get("percentage"));var steps=(List<AcademySetupService.Step>)p.get("steps");assertFalse(steps.stream().filter(step->step.key().equals("SPORTS")).findFirst().orElseThrow().complete());s.setActive(true);assertEquals("REVIEW_NEEDED",service.evaluate(c).get("status"));}
 @Test void managedFacilityMustHaveConfiguredPricingButLegacySetupRulesRemain(){sport(false,true);var area=new AcademyPlayArea();area.setSportId(20L);area.setActive(true);area.setFacilityType("COURT");when(areas.findByAcademyIdOrderByName(10L)).thenReturn(List.of(area));assertEquals("INCOMPLETE",service.evaluate(c).get("status"));area.setHourlyRate(new java.math.BigDecimal("300.00"));assertEquals("REVIEW_NEEDED",service.evaluate(c).get("status"));}
}
